    45  bool IiqDecoder::isAppropriateDecoder(const Buffer* file) {
    46    assert(file);
    47
    48    const DataBuffer db(*file, Endianness::little);
    49
    50    // The IIQ magic. Is present for all IIQ raws.
    51    return db.get<uint32>(8) == 0x49494949;
    52  }
