    54  bool IiqDecoder::isAppropriateDecoder(const TiffRootIFD* rootIFD,
    55                                        const Buffer* file) {
    56    const auto id = rootIFD->getID();
    57    const std::string& make = id.make;
    58
    59    return IiqDecoder::isAppropriateDecoder(file) &&
    60           (make == "Phase One A/S" || make == "Leaf");
    61  }
