    63  // FIXME: this is very close to SamsungV0Decompressor::computeStripes()
    64  std::vector<IiqDecoder::IiqStrip>
    65  IiqDecoder::computeSripes(const Buffer& raw_data,
    66                            std::vector<IiqOffset>&& offsets,
    67                            uint32 height) const {
    68    assert(height > 0);
    69    assert(offsets.size() == (1 + height));
    70
    71    ByteStream bs(DataBuffer(raw_data, Endianness::little));
    72
    73    // so... here's the thing. offsets are not guaranteed to be in
    74    // monotonically increasing order. so for each element of 'offsets',
    75    // we need to find element which specifies next larger offset.
    76    // and only then by subtracting those two offsets we get the slice size.
    77
    78    std::sort(offsets.begin(), offsets.end(),
    79              [](const IiqOffset& a, const IiqOffset& b) {
    80                if (a.offset == b.offset && &a != &b)
    81                  ThrowRDE("Two identical offsets found. Corrupt raw.");
    82                return a.offset < b.offset;
    83              });
    84
    85    std::vector<IiqDecoder::IiqStrip> slices;
    86    slices.reserve(height);
    87
    88    auto offset_iterator = std::begin(offsets);
    89    bs.skipBytes(offset_iterator->offset);
    90
    91    auto next_offset_iterator = std::next(offset_iterator);
    92    while (next_offset_iterator < std::end(offsets)) {
    93      assert(next_offset_iterator->offset > offset_iterator->offset);
    94      const auto size = next_offset_iterator->offset - offset_iterator->offset;
    95      assert(size > 0);
    96
    97      slices.emplace_back(offset_iterator->n, bs.getStream(size));
    98
    99      std::advance(offset_iterator, 1);
   100      std::advance(next_offset_iterator, 1);
   101    }
   102
   103    assert(slices.size() == height);
   104
   105    return slices;
   106  }
