   108  RawImage IiqDecoder::decodeRawInternal() {
   109    const Buffer buf(mFile->getSubView(8));
   110    const DataBuffer db(buf, Endianness::little);
   111    ByteStream bs(db);
   112
   113    bs.skipBytes(4); // Phase One magic
   114    bs.skipBytes(4); // padding?
   115
   116    const auto origPos = bs.getPosition();
   117
   118    const uint32 entries_offset = bs.getU32();
   119
   120    bs.setPosition(entries_offset);
   121
   122    const uint32 entries_count = bs.getU32();
   123    bs.skipBytes(4); // ???
   124
   125    // this is how much is to be read for all the entries
   126    ByteStream es(bs.getStream(entries_count, 16));
   127
   128    bs.setPosition(origPos);
   129
   130    uint32 width = 0;
   131    uint32 height = 0;
   132    uint32 split_row = 0;
   133    uint32 split_col = 0;
   134
   135    Buffer raw_data;
   136    ByteStream block_offsets;
   137    ByteStream wb;
   138    ByteStream correction_meta_data;
   139
   140    for (uint32 entry = 0; entry < entries_count; entry++) {
   141      const uint32 tag = es.getU32();
   142      es.skipBytes(4); // type
   143      const uint32 len = es.getU32();
   144      const uint32 data = es.getU32();
   145
   146      switch (tag) {
   147      case 0x107:
   148        wb = bs.getSubStream(data, len);
   149        break;
   150      case 0x108:
   151        width = data;
   152        break;
   153      case 0x109:
   154        height = data;
   155        break;
   156      case 0x10f:
   157        raw_data = bs.getSubView(data, len);
   158        break;
   159      case 0x110:
   160        correction_meta_data = bs.getSubStream(data);
   161        break;
   162      case 0x21c:
   163        // they are not guaranteed to be sequential!
   164        block_offsets = bs.getSubStream(data, len);
   165        break;
   166      case 0x21d:
   167        black_level = data >> 2;
   168        break;
   169      case 0x222:
   170        split_col = data;
   171        break;
   172      case 0x224:
   173        split_row = data;
   174        break;
   175      default:
   176        // FIXME: is there a "block_sizes" entry?
   177        break;
   178      }
   179    }
   180
   181    // FIXME: could be wrong. max "active pixels" in "Sensor+" mode - "101 MP"
   182    if (width == 0 || height == 0 || width > 11608 || height > 8708)
   183      ThrowRDE("Unexpected image dimensions found: (%u; %u)", width, height);
   184
   185    if (split_col > width || split_row > height)
   186      ThrowRDE("Invalid sensor quadrant split values (%u, %u)", split_row,
   187               split_col);
   188
   189    block_offsets = block_offsets.getStream(height, sizeof(uint32));
   190
   191    std::vector<IiqOffset> offsets;
   192    offsets.reserve(1 + height);
   193
   194    for (uint32 row = 0; row < height; row++)
   195      offsets.emplace_back(row, block_offsets.getU32());
   196
   197    // to simplify slice size calculation, we insert a dummy offset,
   198    // which will be used much like end()
   199    offsets.emplace_back(height, raw_data.getSize());
   200
   201    const std::vector<IiqStrip> strips(
   202        computeSripes(raw_data, std::move(offsets), height));
   203
   204    mRaw->dim = iPoint2D(width, height);
   205    mRaw->createData();
   206
   207    DecodePhaseOneC(strips, width, height);
   208    if (correction_meta_data.getSize() != 0 && iiq)
   209      CorrectPhaseOneC(correction_meta_data, split_row, split_col);
   210
   211    for (int i = 0; i < 3; i++)
   212      mRaw->metadata.wbCoeffs[i] = wb.getFloat();
   213
   214    return mRaw;
   215  }
